mapper.select:
SELECT A.PROGRM_FILE_NM, A.BOOKMARKS_ORDER, B.URL, A.BOOKMARKS_NAME, B.PROGRM_KOREAN_NM
FROM tb_bookmarks A
INNER JOIN COMTNPROGRMLIST B ON A.PROGRM_FILE_NM = B.PROGRM_FILE_NM
WHERE A.USER_ID = #{params.userId}
  AND A.USER_GUBUN = #{params.userGubun}
ORDER BY A.BOOKMARKS_ORDER ASC

mapper.update:
UPDATE tb_bookmarks
SET BOOKMARKS_ORDER = CASE PROGRM_FILE_NM

    WHEN #{item.progrmFileNm} THEN #{item.bookmarksOrder,jdbcType=VARCHAR}

ELSE BOOKMARKS_ORDER END,
LAST_UPDUSR_ID = #{userId},
LAST_UPDT_PNTTM = NOW()
WHERE USER_ID = #{userId}
  AND PROGRM_FILE_NM IN

    #{item.progrmFileNm}
